"use client"

import animation from "react-useanimations/lib/coffee"

import { UseAnimation, type UseAnimationProps } from "@/components/use-animation"

// "Coffee" from https://useanimations.com (MIT): https://useanimations.com/icons/coffee
export function AnimatedCoffee(
  props: Omit<UseAnimationProps, "animationData">
) {
  return (
    <UseAnimation
      animationData={animation.animationData}
      interaction="hover-replay"
      {...props}
    />
  )
}
